    imageHint: "Parangul Mare peak rocky landscape",
    descriptionAdvanced: {
      de: "Der Parângul Mare ist mit einer Höhe von 2.519 Metern der dritthöchste Gipfel Rumäniens und der höchste Punkt des Parâng-Massivs in den Südkarpaten. Im Gegensatz zu den gut erschlossenen Massiven wie Bucegi oder Făgăraș ist der Parângul Mare für seine Wildheit und Unberührtheit bekannt, da keine befestigten Straßen direkt zum Gipfel führen. Die Geomorphologie ist durch beeindruckende Gletscherformen geprägt, darunter tiefe Kare und kristallklare Gletscherseen wie Roșiile und Mândra. Der Aufstieg zum Gipfel ist anspruchsvoll und erfordert gute Kondition sowie Orientierungsvermögen, belohnt jedoch mit einem unvergleichlichen Panorama über die umliegenden Gebirge wie Retezat und Șureanu. Die Vegetation oberhalb der Baumgrenze besteht aus alpinen Rasen und Flechten, während Gämsen und Steinadler in den felsigen Regionen heimisch sind. Historisch wurde das Gebiet für die Wanderweidewirtschaft genutzt, heute ist es ein Magnet für erfahrene Bergsteiger und Naturliebhaber.",
      hu: "A Parângul Mare 2519 méteres magasságával Románia harmadik legmagasabb csúcsa, és a Déli-Kárpátokban található Parâng-masszívum legmagasabb pontja. A jól kiépített hegységekkel, mint a Bucsecs vagy a Fogaras, ellentétben a Parângul Mare vadságáról és érintetlenségéről híres, mivel nem vezetnek kiépített utak közvetlenül a csúcsra. Geomorfológiáját lenyűgöző gleccserformák jellemzik, köztük mély kárfülkék és kristálytiszta gleccsertavak, mint a Roșiile és a Mândra. A csúcsra való feljutás nehéz, jó állóképességet és tájékozódási képességet igényel, de a kilátás kárpótol, hiszen páratlan panoráma nyílik a környező hegységekre, például a Retyezátra és a Sebes-hegységre. A fahatár feletti növényzet alpesi gyepekből és zuzmókból áll, míg a zergék és a szirti sasok a sziklás régiókban honosak. Történelmileg a területet transzhumáló pásztorkodásra használták, ma pedig a tapasztalt hegymászók és természetkedvelők mágnese.",
      ro: "Parângul Mare, cu o altitudine de 2.519 metri, este al treilea cel mai înalt vârf din România și cel mai înalt punct al masivului Parâng din Carpații Meridionali. Spre deosebire de masivele bine dezvoltate turistic, cum ar fi Bucegi sau Făgăraș, Parângul Mare este cunoscut pentru sălbăticia și puritatea sa, deoarece nu există drumuri asfaltate care să ducă direct la vârf. Geomorfologia sa este marcată de forme glaciare impresionante, inclusiv circuri adânci și lacuri glaciare cristaline precum Roșiile și Mândra. Ascensiunea spre vârf este solicitantă și necesită o condiție fizică bună, dar recompensa este o panoramă inegalabilă asupra munților din jur, cum ar fi Retezat și Șureanu. Vegetația de deasupra limitei pădurii constă în pajiști alpine și licheni, în timp ce caprele negre și acvilele de munte sunt frecvente în regiunile stâncoase. Istoric, zona a fost utilizată pentru transhumanță, iar astăzi este un punct de atracție pentru alpiniștii experimentați și iubitorii de natură.",
      en: "Parângul Mare, standing at 2,519 meters, is the third-highest peak in Romania and the highest point of the Parâng Massif in the Southern Carpathians. Unlike well-developed massifs such as Bucegi or Făgăraș, Parângul Mare is known for its wildness and pristine state, as no paved roads lead directly to the summit. Its geomorphology is characterized by impressive glacial landforms, including deep cirques and crystal-clear glacial lakes like Roșiile and Mândra. The ascent to the summit is challenging and requires good fitness and navigation skills, but it rewards hikers with an unparalleled panorama of surrounding ranges like Retezat and Șureanu. Vegetation above the tree line consists of alpine meadows and lichens, while chamois and golden eagles are native to the rocky regions. Historically, the area was used for transhumance pastoralism, and today it remains a magnet for experienced mountaineers and nature enthusiasts.",
      es: "Con 2.519 metros, el Parângul Mare es el pico más alto de las montañas de Parâng en Rumanía. Situado en los Cárpatos Meridionales, es un destino popular para los montañistas. La zona es conocida por su paisaje alpino con lagos glaciares, morrenas y cumbres áridas. El ascenso es exigente, pero las vistas recompensan con un panorama sobre las cadenas montañosas circundantes. Cerca se encuentran las estaciones de esquí de Petroșani y Lupeni.",
      pt: "Com 2.519 metros, o Parângul Mare é o pico mais alto das montanhas de Parâng, na Roménia. Situado nos Cárpatos Meridionais, é um destino popular para montanhistas. A área é conhecida pela sua paisagem alpina com lagos glaciares, morenas e picos áridos. A subida é exigente, mas a vista compensa com um panorama sobre as montanhas circundantes. Nas proximidades encontram-se as estâncias de esqui de Petroșani e Lupeni.",
      fr: "Culminant à 2 519 mètres, le Parângul Mare est le plus haut sommet des monts Parâng en Roumanie. Situé dans les Carpates méridionales, c'est une destination prisée des alpinistes. La région est réputée pour son paysage alpin composé de lacs glaciaires, de moraines et de sommets arides. L'ascension est exigeante, mais la vue offre un panorama exceptionnel sur les massifs environnants. Les stations de ski de Petroșani et Lupeni se trouvent à proximité.",
    },
