      en: ["Elevation: 2,405 meters", "Range: Parâng Mountains", "Hiking destination", "Alpine setting"],
      es: ["Altitud: 2.405 metros", "Montañas: Parâng", "Destino de senderismo", "Entorno alpino"],
      pt: ["Altitude: 2.405 metros", "Montanhas: Parâng", "Destino de caminhada", "Ambiente alpino"],
      fr: ["Altitude : 2 405 mètres", "Monts : Parâng", "Destination de randonnée", "Environnement alpin"],
