      hu: "A Țibleș-csúcs a Țibleș-hegység legmagasabb pontja Észak-Romániában. Magassága eléri az 1839 métert.",
      ro: "Vârful Țibleș este cel mai înalt punct din Munții Țibleș, în nordul României. Acesta atinge 1839 metri.",
      en: "Țibleș Peak is the highest point in the Țibleș Mountains in northern Romania. It reaches 1,839 meters.",
