      en: ["Elevation: 2,025 meters", "Range: Călimani Mountains", "Eastern Carpathians", "Alpine mountain chain"],
      es: ["Altura: 2.025 metros", "Montañas: Călimani", "Cárpatos Orientales", "Cadena montañosa alpina"],
      pt: ["Altitude: 2.025 metros", "Montanhas: Călimani", "Cárpatos Orientais", "Cadeia de montanhas alpina"],
