    imageHint: "Ihnat peak Calimani",
    descriptionAdvanced: {
      de: "Der Gipfel Ihnat (Vârful Ihnat) ist eine markante Erhebung im Maramureș-Gebirge im Norden Rumäniens, nahe der Grenze zur Ukraine. Mit einer Höhe von etwa 1439 Metern ist er Teil eines wilden und abgelegenen Gebirgsmassivs, das für seine unberührte Natur bekannt ist. Die Geologie des Berges ist durch metamorphes Gestein und kristalline Schiefer geprägt, was typisch für den nördlichen Teil der rumänischen Ostkarpaten ist. Die Hänge sind mit dichten Buchen- und Fichtenwäldern bedeckt, die in den höheren Lagen in Bergwiesen übergehen. Diese Wiesen bieten im Sommer eine beeindruckende Vielfalt an alpinen Blumen und Heilkräutern. Aufgrund seiner Lage in der Nähe der Staatsgrenze war der Zugang zum Ihnat lange Zeit eingeschränkt, was zur Erhaltung seiner ursprünglichen Flora und Fauna beigetragen hat. Wanderer schätzen die Einsamkeit und die weiten Ausblicke auf die ukrainischen Karpaten und das Tal von Poienile de sub Munte. Die Region ist auch kulturell bedeutend für die dort lebende huzulische und ukrainische Minderheit.",
      hu: "Az Ihnat-csúcs (Vârful Ihnat) a Máramarosi-havasok egyik jelentős hegycsúcsa Románia északi részén, közvetlenül az ukrán határ közelében. 1439 méteres magasságával a hegység vadabb, kevésbé látogatott vonulataihoz tartozik, ahol a természet még megőrizte ősi állapotát. A hegy felépítését kristályos palák és metamorf kőzetek határozzák meg, ami éles kontrasztot mutat a délebbi vulkáni területekkel. A csúcs környékén kiterjedt hegyi legelők találhatóak, amelyek a hagyományos havasi pásztorkodás fontos helyszínei voltak évszázadokon át. A kilátás a csúcsról lenyűgöző, rálátást biztosítva az ukrajnai Kárpátok vonulataira és a Ruszpolyána-völgyre. A terület nehéz megközelíthetősége miatt a biológiai sokféleség kiemelkedő, ritka ragadozó madarak és hegyi emlősök találnak itt menedéket. Turisztikai szempontból a bakancsos túrázók számára vonzó, akik a tömegturizmustól mentes, kihívást jelentő útvonalakat keresik ezen a határmenti vidéken.",
      ro: "Vârful Ihnat este o eminență geografică importantă din Munții Maramureșului, situat în proximitatea frontierei de stat cu Ucraina. Cu o altitudine de 1439 de metri, vârful oferă o perspectivă inedită asupra peisajului nordic al Carpaților Orientali, fiind parte a unui masiv caracterizat prin sălbăticie. Structura sa geologică este formată din șisturi cristaline, reflectând istoria tectonică complexă a zonei Maramureșului. Pantele muntelui sunt acoperite de păduri vaste de foioase și conifere, care adăpostesc un ecosistem bogat și diversificat. În perioada estivală, creasta muntelui devine un loc propice pentru pășunatul tradițional, o activitate cu rădăcini adânci în cultura locală a huțulilor. Accesul în zonă necesită adesea informarea autorităților de frontieră, fapt ce a menținut un nivel scăzut de antropizare a mediului. Vârful reprezintă un simbol al rezilienței naturii și un punct de atracție pentru turiștii care caută itinerarii montane autentice și izolate.",
      en: "Ihnat Peak (Vârful Ihnat) is a significant mountain summit in the Maramureș Mountains of northern Romania, standing at an elevation of 1439 meters. Located very close to the Ukrainian border, it forms part of a rugged and remote landscape within the Eastern Carpathians. The peak is characterized by its crystalline schist geology, contributing to its steep slopes and rocky outcrops. The surrounding environment is dominated by vast primeval forests of beech and spruce, which are home to a variety of protected wildlife species. High-altitude meadows, known locally as poloninas, cover the summit area, offering spectacular panoramic views of the Transcarpathian region. Historically, this area has been influenced by the cultural traditions of the Hutsul people, who have used these mountains for pastoral activities for generations. Today, Ihnat Peak remains a destination for adventurous hikers seeking solitude and a chance to experience the raw natural beauty of one of Europe's last wild mountain areas.",
      es: "El pico Ihnat se encuentra en las montañas de Maramureș, en los Cárpatos Orientales, y alcanza una altura de 1.870 m. Es un pico mirador popular con vistas a las colinas de Maramureș y las montañas de Rodna. La roca se compone principalmente de sedimentos tipo flysch y arenisca. La región está densamente boscosa y es rica en vida silvestre. El Ihnat es accesible a través de rutas de senderismo señalizadas. En las cercanías hay varias iglesias tradicionales de madera.",
      pt: "O pico Ihnat está localizado nas montanhas Maramureș, nos Cárpatos Orientais, e atinge uma altura de 1.870 m. É um pico miradouro popular com vista para as colinas de Maramureș e as montanhas Rodna. A rocha consiste principalmente de sedimentos tipo flysch e arenito. A região é densamente florestada e rica em vida selvagem. O Ihnat é acessível através de trilhos de caminhada marcados. Nas proximidades existem várias igrejas tradicionais de madeira.",
      fr: "Le sommet Ihnat est situé dans les monts Maramureș, au sein des Carpates orientales, et culmine à 1 870 m. C'est un point de vue panoramique apprécié offrant un regard sur les collines du Maramureș et les monts Rodna. La roche est principalement composée de sédiments de type flysch et de grès. La région est densément boisée et riche en faune sauvage. L'Ihnat est accessible par des sentiers de randonnée balisés. Plusieurs églises en bois traditionnelles se trouvent à proximité.",
    },
    factsAdvanced: {
      de: ["Der Ihnat Gipfel liegt auf einer Höhe von 1439 Metern über dem Meeresspiegel.", "Er befindet sich im Maramureș-Gebirge in unmittelbarer Nähe zur Ukraine.", "Geologisch besteht das Massiv überwiegend aus kristallinen Schiefern.", "Der Berg ist Teil des Naturparks Maramureș-Gebirge.", "Wanderungen erfordern oft eine Anmeldung beim rumänischen Grenzschutz.", "Die Region ist bekannt für ihre traditionelle Almwirtschaft der Huzulen."],
      hu: ["Az Ihnat-csúcs tengerszint feletti magassága 1439 méter.", "A hegy a Máramarosi-havasok északi, határmenti övezetében található.", "A csúcsról tiszta időben jól láthatóak az ukrajnai Kárpátok vonulatai.", "A terület a Máramarosi-havasok Natúrpark része.", "A környéken számos ritka havasi növényfaj, például az encián is megtalálható.", "A hagyományos pásztorkodás ma is élő hagyomány a hegy lábánál fekvő falvakban."],
      ro: ["Vârful Ihnat atinge înălțimea de 1439 de metri.", "Este situat în Munții Maramureșului, județul Maramureș.", "Vârful se află pe linia de frontieră dintre România și Ucraina.", "Compoziția geologică principală este reprezentată de șisturile cristaline.", "Face parte din Parcul Natural Munții Maramureșului.", "Traseele de acces pornesc de regulă din localitatea Poienile de sub Munte."],
      en: ["The summit reaches a height of 1439 meters above sea level.", "It is located in the Maramureș Mountains, near the village of Poienile de sub Munte.", "The peak lies on the ridge that marks the border with Ukraine.", "Geological formations here date back to the Paleozoic era.", "The area is protected as part of a national natural park.", "It is a key site for observing large birds of prey like the golden eagle."],
      es: ["Altitud: 1.870 m", "Montañas: Maramureș", "Roca: Flysch y arenisca", "Refugio: Cabana Ihnat a 1.400 m", "Distancia a Sighetu Marmației: 25 km", "Tiempo de caminata: 3 horas desde el valle"],
      pt: ["Altitude: 1.870 m", "Montanhas: Maramureș", "Rocha: Flysch e arenito", "Refúgio: Cabana Ihnat a 1.400 m", "Distância de Sighetu Marmației: 25 km", "Tempo de caminhada: 3 horas do vale"],
      fr: ["Altitude : 1 870 m", "Massif : Maramureș", "Roche : Flysch et grès", "Refuge : Cabana Ihnat à 1 400 m", "Distance de Sighetu Marmației : 25 km", "Temps de randonnée : 3 heures depuis la vallée"],
    },
