      hu: ["Legmagasabb csúcs: Madarasi-Hargita (1801m)", "Hegység: Keleti-Kárpátok", "Vulkáni eredet", "A Székelyföld központi pontja"],
      ro: ["Vârf principal: Madarasi-Hargita (1801m)", "Masiv: Carpații Orientali", "Origine vulcanică", "Punct central al Ținutului Secuiesc"],
