      en: ["Maximum elevation of 1608 meters", "Located in the Lotru Mountains of the Southern Carpathians", "Composed mainly of crystalline schists", "Critical habitat for brown bears and wolves", "Watershed between the Lotru and Latorița river basins", "Snow cover often lasts until late May"],
      es: ["Altura de 1608 metros sobre el nivel del mar", "Parte de las montañas Lotru en los Cárpatos del Sur", "Compuesto principalmente de roca metamórfica", "Hábitat importante para osos pardos y lobos", "Limita con las cuencas de Lotru y Latorița", "La capa de nieve a menudo permanece hasta mayo"],
