      pt: ["Altura máxima de 1411 metros", "Parte das montanhas Lotru na Romênia", "Tipos de rocha incluem gnaisse e xisto", "O nome traduz-se como 'Faia Alta'", "Local importante para a agricultura alpina histórica", "Oferece vista para o vale do Lotru"],
