      es: ["Altitud de 1.227 metros en las montañas de Trascău", "Punto más alto de la meseta caliza de Bedeleu", "Contiene caliza del Jurásico con fenómenos kársticos", "Situado cerca de las cascadas de Şipote", "Zona tradicional de pastoreo de los Motzen (Moți)", "Lugar importante para especies raras de orquídeas"],
      pt: ["Altitude de 1.227 metros nas montanhas de Trascău", "Ponto mais alto do planalto de calcário de Bedeleu", "Contém calcário do Jurássico com fenómenos cársticos", "Situado perto das cascatas de Şipote", "Zona tradicional de pastoreio dos Motzen (Moți)", "Local importante para espécies raras de orquídeas"],
      fr: ["Altitude de 1 227 mètres dans les monts Trascău", "Point culminant du plateau calcaire de Bedeleu", "Présence de calcaire jurassique avec phénomènes karstiques", "Situé à proximité des cascades de Şipote", "Zone de pâturage traditionnelle des Motzes (Moți)", "Site majeur pour des espèces d'orchidées rares"],
