      en: ["Maximum elevation of 1501 meters", "Composed of ancient metamorphic rocks", "Watershed for tributaries of the Lotru River", "Features extensive blueberry and cranberry fields", "Habitat for red deer and mountain birds of prey", "Significant point for regional geodetic surveys"],
      es: ["Altura de 1501 metros sobre el nivel del mar", "Formado por rocas metamórficas antiguas", "Divisoria de aguas de los afluentes del Lotru", "Presencia de campos de arándanos y arándanos rojos", "Hábitat para ciervos y aves rapaces", "Punto importante para mediciones geodésicas"],
      pt: ["Altitude de 1501 metros acima do nível do mar", "Composto por rochas metamórficas antigas", "Bacia hidrográfica para afluentes do Lotru", "Ocorrência de campos de mirtilo e oxicoco", "Habitat para veados e aves de rapina", "Ponto importante para medições geodésicas"],
      fr: ["Altitude de 1 501 mètres au-dessus du niveau de la mer", "Composé de roches métamorphiques anciennes", "Ligne de partage des eaux pour les affluents du Lotru", "Présence de champs de myrtilles et d'airelles", "Habitat pour le cerf élaphe et les oiseaux de proie", "Point important pour les relevés géodésiques"],
