    imageHint: "Detunata Flocoasa forest",
    descriptionAdvanced: {
      de: "Detunata Flocoasa ist mit 1258 Metern der höhere der beiden markanten Basaltgipfel im Siebenbürgischen Erzgebirge. Im Gegensatz zu seinem kahlen Nachbarn, der Detunata Goala, ist dieser Gipfel fast vollständig von dichten Fichten- und Nadelwäldern bedeckt, was ihm seinen Beinamen flocoasa (auf Deutsch etwa fussig oder zottig) einbrachte. Trotz der Bewaldung verbirgt der Berg unter seinem grünen Mantel die gleichen beeindruckenden basaltischen Säulenstrukturen vulkanischen Ursprungs. Diese entstanden während der Abkühlungsphase magmatischer Ergüsse im Tertiär und zeugen von der dynamischen geologischen Vergangenheit der Apuseni-Region. Der Aufstieg zum Gipfel führt durch schattige Waldwege und bietet an lichten Stellen faszinierende Ausblicke auf die umliegenden Täler und die Bergwelt der Motzen. Botanisch gesehen bietet das Gebiet eine hohe Diversität an Moosen und Farnen, die im kühleren, feuchten Mikroklima unter den Felsen gedeihen. Die Detunata Flocoasa ist Teil eines geschützten Naturkomplexes, der sowohl geologische als auch biologische Schutzziele verfolgt. Für Naturforscher stellt der Kontrast zwischen den beiden Detunata-Gipfeln ein klassisches Beispiel für den Einfluss der Exposition und Vegetation auf die Verwitterung von Gesteinsformationen dar.",
      hu: "A Detunáta Fenyves, románul Detunata Flocoasa, az Erdélyi-érchegység egyik legmagasabb és legjellegzetesebb bazaltcsúcsa. Az 1258 méter magas hegy nevét a rajta elterülő sűrű fenyőerdőről kapta, amely szinte teljesen elborítja a bazaltsziklákat, ellentétben a mellette lévő Kopasz-Detunátával. A flocoasa jelző jelentése szőrös vagy bozontos, ami a távolról szemlélt növényzet textúrájára utal. A hegy gyomrában azonban ugyanolyan szabályos bazaltoszlopok találhatók, mint testvérhegyén, amelyek a harmadidőszaki vulkáni tevékenység során jöttek létre. A sűrű erdőtakaró hűvösebb és párásabb mikroklímát biztosít, ami kedvez a különleges mohafajok és páfrányok elterjedésének a sziklák tövében. A csúcsra vezető út nehezebben járható, mint a szomszédos csúcson, de a természet érintetlensége kárpótolja a látogatókat. A terület a romániai természetvédelem egyik fontos bástyája, ahol a geológiai értékek mellett a biológiai sokféleség megőrzése is prioritást élvez. A két csúcs közötti kontraszt kiváló szemléltetője annak, hogyan változtatja meg a növényzet egy táj arculatát és láthatóságát.",
      ro: "Vârful Detunata Flocoasă este fratele mai înalt al celebrei Detunate Goale, atingând o altitudine de 1258 de metri în inima Munților Metaliferi. Numele său sugestiv provine de la faptul că, spre deosebire de geamăna sa, este acoperit aproape în totalitate de o pădure deasă de molid, care îi conferă un aspect flocos sau lânos atunci când este privit de la distanță. Deși coloanele de bazalt sunt mai puțin vizibile sub stratul de vegetație, structura sa geologică este identică, fiind formată tot prin răcirea lavei vulcanice în perioadele geologice trecute. Această vegetație abundentă creează un microclimat umed și răcoros, favorabil dezvoltării unei flore diverse formate din mușchi și ferigi rare care cresc la baza grohotișurilor de bazalt. Traseul către acest vârf oferă o experiență de drumeție mai sălbatică și mai liniștită, fiind mai puțin frecventat de turiști decât varianta goală. Rezervația naturală protejează întregul complex, asigurând conservarea habitatelor forestiere și a formelor de relief vulcanice. Detunata Flocoasă rămâne un simbol al rezilienței naturii, unde pădurea reușește să stăpânească rocile dure de origine magmatică.",
      en: "Detunata Flocoasa is the higher twin of the famous Detunata Goala, reaching an altitude of 1258 meters in the Metaliferi Mountains. Its name, which translates to shaggy or fuzzy, is derived from the thick spruce forests that cover nearly the entire peak, concealing the basaltic structures beneath. Despite the dense vegetation, the mountain shares the same volcanic origin as its neighbor, featuring impressive columnar basalt formations created by Neogene magmatic cooling. This forest cover provides a unique microclimate that supports a rich diversity of mosses, ferns, and other shade-loving plants at the base of the cliffs. Hiking to the summit of Detunata Flocoasa offers a more secluded and wild experience compared to the more accessible and bare Detunata Goala. The area is part of a larger protected natural complex intended to preserve both the unique geological features and the surrounding forest ecosystems. For scientists, the contrast between the two peaks serves as an excellent case study in how vegetation affects the visibility and weathering of volcanic landforms.",
      es: "El Detunata Flocoasă (Vârful Detunata Flocoasă) es un destacado cono volcánico en las montañas Metaliferi, parte de los montes Apuseni en Rumanía, a 1.296 metros. Su nombre significa 'Detunata velluda' en contraste con la vecina 'calva' Detunata Goală. La montaña está compuesta de andesita y basalto. Las laderas están cubiertas de densos bosques de hayas y robles, de ahí su nombre. La fauna incluye jabalíes, ciervos y diversas especies de aves. Históricamente, también se practicó aquí la minería, principalmente de oro y plata. El pico es menos conocido y de difícil acceso, pero ofrece una experiencia natural tranquila.",
      pt: "O Detunata Flocoasă (Vârful Detunata Flocoasă) é um cone vulcânico proeminente nas montanhas Metaliferi, cordilheira Apuseni, Romênia, a 1.296 metros. O nome significa 'Detunata peluda', em contraste com a vizinha 'calva' Detunata Goală. A montanha consiste em andesito e basalto. As encostas são cobertas por densas florestas de faias e carvalhos, daí o nome. A fauna inclui javalis, veados e várias espécies de aves. Historicamente, a mineração também foi realizada aqui, principalmente de ouro e prata. O pico é menos conhecido e mais difícil de acessar, mas oferece uma experiência de natureza tranquila.",
      fr: "Le Detunata Flocoasă (Vârful Detunata Flocoasă) est un cône volcanique remarquable situé dans les monts Metaliferi, dans le massif des Apuseni en Roumanie, culminant à 1 296 mètres. Son nom signifie 'Detunata duveteuse', par opposition à la Detunata Goală voisine, qualifiée de 'chauve'. La montagne est composée d'andésite et de basalte. Les pentes sont couvertes de denses forêts de hêtres et de chênes, ce qui lui a valu son nom. La faune comprend des sangliers, des cerfs et diverses espèces d'oiseaux. Historiquement, l'exploitation minière y était pratiquée, principalement pour l'or et l'argent. Le sommet est moins connu et plus difficile d'accès, mais offre une expérience de nature paisible.",
    },
